package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Defers the claim until the given date (see ClaimDue#deferred). Only an OPEN claim is deferred, only to a date after
 * the sheet's today; a claim whose due-by falls inside a closed period is refused.
 */
public class ApplyDefer {
    public void apply(@Val Claim claim, @Val ClaimDeferral deferral, SheetRepository sheets, PeriodRepository periods,
            Out<Claim> changed) throws InvalidClaimStatusException {
        if (claim.status() != ClaimStatus.OPEN) {
            throw new InvalidClaimStatusException("Only an OPEN claim can be deferred");
        }
        if (!deferral.until().isAfter(sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("A claim is deferred only to a date after today");
        }
        if (periods.closedOn(claim.sheetId(), claim.dueBy())) {
            throw new InvalidClaimStatusException("The claim's due-by is inside a closed period");
        }
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                claim.note(), claim.status(), claim.number(), claim.due(), claim.openedBy(), claim.stated(),
                claim.statedDue(), claim.corrects(), claim.dueBy(), deferral.until(), claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags(), claim.held()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Stores the deferral, but only while the claim is still OPEN, logged as made on the sheet's today; a change another user made first is refused. */
public class SaveDefer {
    public void save(@Val Claim claim, ClaimRepository claims, SheetRepository sheets, Out<Claim> saved) throws InvalidClaimStatusException {
        if (!claims.defer(claim, sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
        saved.set(claim);
    }
}
# PUT /api/sheets/{sheetId}/claims/{claimId}/defer — defer an OPEN claim until a date after the sheet's today: until
# the sheet's today reaches that date the claim counts in no total, is not overdue, cannot be settled and is left
# unbound by a statement. A claim that is not OPEN, a date not after today (or not a date), or a claim whose due-by falls inside a
# closed period, is a 409 and a claim not on the sheet a 404, neither writing anything. Responds with the claim as
# stored.
validate:
  class: net.officefloor.hq.app.claim.ValidateDefer
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyDefer
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveDefer
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimDeferred
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Takes the sheet's figures before the change, so its audit step can write the ones it moved. */
public class TakeRollup {
    public void take(@PathVariable("sheetId") String sheetId, Rollup rollup, Out<RollupBefore> before) {
        before.set(rollup.take(sheetId.trim()));
    }
}

