cat > $d/ApplyClaimHold.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Holds or releases the claim: only an OPEN or PENDING claim is. While held and not bound by a statement it counts in
 *  no live total, as a claim dated within a hold of its person does (see ClaimDue#countsLive). A claim already as asked
 *  is left as it is. */
public class ApplyClaimHold {
    public void apply(@Val Claim claim, @Val ClaimHold hold, Out<Claim> changed, Out<ClaimHoldChange> change)
            throws InvalidClaimStatusException {
        if (!ClaimDue.isOpen(claim)) {
            throw new InvalidClaimStatusException("Only an OPEN or PENDING claim can be held or released");
        }
        change.set(new ClaimHoldChange(claim.held() != hold.held()));
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                claim.note(), claim.status(), claim.number(), claim.due(), claim.openedBy(), claim.stated(),
                claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(),
                claim.splitFrom(), claim.ref(), claim.tags(), hold.held()));
    }
}
EOF
cat > $d/SaveClaimHold.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Stores the hold or release, but only while the claim is still OPEN or PENDING and not already so; a change another
 *  user made first is refused. Nothing is written when the claim already was as asked. */
public class SaveClaimHold {
    public void save(@Val Claim claim, @Val ClaimHoldChange change, ClaimRepository claims)
            throws InvalidClaimStatusException {
        if (change.changed() && !claims.hold(claim)) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
    }
}
EOF
cat > $d/RecordClaimHold.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_HELD or CLAIM_RELEASED to the audit file once the change is stored, naming the claim
 *  (number=<number> when it has one), then the figures the change moved (see Rollup). Nothing when nothing changed. */
public class RecordClaimHold {
    public void record(@Val Claim claim, @Val ClaimHold hold, @Val ClaimHoldChange change, PersonRepository people,
            @Val RollupBefore before, Rollup rollup, Audit audit) {
        if (!change.changed()) {
            return;
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record((hold.held() ? "CLAIM_HELD" : "CLAIM_RELEASED") + " sheet=" + claim.sheetId() + " by=" + hold.by()
                + " person=" + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date() + (claim.number() == null ? "" : " number=" + claim.number()));
        rollup.record(claim.sheetId(), hold.by(), before);
    }
}
EOF
